[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Montserrat:wght@600;700;800&display=swap" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.2.0/fonts/remixicon.css" rel="stylesheet">
  <style>
    /* ===== RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: #2d2d2d;
      background: #fff;
      line-height: 1.6;
      overflow-x: hidden;
    }
    a { text-decoration: none; color: inherit; }
    ul { list-style: none; }
    img { max-width: 100%; display: block; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    /* ===== VARIABLES ===== */
    :root {
      --red: #C41E3A;
      --red-dark: #a1182f;
      --red-light: #e8384f;
      --navy: #1B3A5C;
      --navy-dark: #122a44;
      --navy-light: #2a5280;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --warm-gray: #F5F3F0;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
      --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --transition: 0.25s ease;
    }

    /* ===== TYPOGRAPHY ===== */
    h1, h2, h3, h4 { font-family: 'Montserrat', 'Inter', sans-serif; line-height: 1.2; color: var(--navy); }
    h1 { font-size: clamp(2rem, 5vw, 3.25rem); font-weight: 800; letter-spacing: -0.02em; }
    h2 { font-size: clamp(1.5rem, 3.5vw, 2.25rem); font-weight: 700; letter-spacing: -0.01em; }
    h3 { font-size: clamp(1.1rem, 2vw, 1.35rem); font-weight: 600; }
    p { color: var(--gray-600); }

    .section-label {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--red);
      margin-bottom: 0.75rem;
    }

    /* ===== LAYOUT ===== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    section { padding: 80px 0; }

    /* ===== BUTTONS ===== */
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 32px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 0.95rem;
      transition: all var(--transition);
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--red);
      color: var(--white);
      box-shadow: 0 4px 14px rgba(196,30,58,0.35);
    }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: 0 6px 20px rgba(196,30,58,0.4); }
    .btn-secondary {
      background: var(--white);
      color: var(--navy);
      border: 2px solid var(--navy);
    }
    .btn-secondary:hover { background: var(--navy); color: var(--white); }
    .btn-ghost {
      background: transparent;
      color: var(--white);
      border: 2px solid rgba(255,255,255,0.5);
    }
    .btn-ghost:hover { border-color: var(--white); background: rgba(255,255,255,0.1); }
    .btn-sm { padding: 10px 22px; font-size: 0.85rem; }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow var(--transition);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }
    .header-top {
      background: var(--navy);
      color: var(--white);
      font-size: 0.8rem;
      padding: 6px 0;
    }
    .header-top .container {
      display: flex;
      justify-content: flex-end;
      align-items: center;
      gap: 20px;
    }
    .header-top a { color: rgba(255,255,255,0.8); transition: color var(--transition); }
    .header-top a:hover { color: var(--white); }
    .header-top .divider { width: 1px; height: 14px; background: rgba(255,255,255,0.25); }
    .header-main .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 70px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Montserrat', sans-serif;
      font-weight: 800;
      font-size: 1.2rem;
      color: var(--navy);
    }
    .logo i { font-size: 1.6rem; color: var(--red); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }
    .nav-links a {
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-700);
      transition: color var(--transition);
      position: relative;
    }
    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--red);
      transition: width var(--transition);
    }
    .nav-links a:hover { color: var(--red); }
    .nav-links a:hover::after { width: 100%; }
    .nav-donate-btn {
      background: var(--red);
      color: var(--white) !important;
      padding: 10px 24px;
      border-radius: 50px;
      font-weight: 600;
      box-shadow: 0 2px 8px rgba(196,30,58,0.3);
      transition: all var(--transition);
    }
    .nav-donate-btn::after { display: none !important; }
    .nav-donate-btn:hover { background: var(--red-dark) !important; transform: translateY(-1px); color: var(--white) !important; }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      z-index: 1002;
    }
    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--navy);
      border-radius: 2px;
      transition: all 0.3s ease;
    }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile nav */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      right: -100%;
      width: 300px;
      max-width: 85vw;
      height: 100vh;
      background: var(--white);
      z-index: 1001;
      padding: 90px 32px 32px;
      box-shadow: var(--shadow-xl);
      transition: right 0.35s ease;
      overflow-y: auto;
    }
    .mobile-nav.open { right: 0; }
    .mobile-nav a {
      display: block;
      padding: 14px 0;
      font-size: 1.05rem;
      font-weight: 500;
      color: var(--gray-700);
      border-bottom: 1px solid var(--gray-100);
      transition: color var(--transition);
    }
    .mobile-nav a:hover { color: var(--red); }
    .mobile-nav .mobile-donate {
      margin-top: 20px;
      display: block;
      text-align: center;
      background: var(--red);
      color: var(--white);
      padding: 14px;
      border-radius: 50px;
      font-weight: 600;
      border-bottom: none;
    }
    .mobile-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.4);
      z-index: 1000;
      opacity: 0;
      transition: opacity 0.3s ease;
    }
    .mobile-overlay.show { opacity: 1; }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 600px;
      display: flex;
      align-items: center;
      padding: 140px 0 100px;
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 50%, #0d1f33 100%);
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 800px;
      height: 800px;
      background: radial-gradient(circle, rgba(196,30,58,0.15) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 120px;
      background: linear-gradient(to top, var(--white), transparent);
      pointer-events: none;
    }
    .hero .container {
      position: relative;
      z-index: 2;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }
    .hero-content { max-width: 560px; }
    .hero-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(196,30,58,0.15);
      color: var(--red-light);
      padding: 6px 16px;
      border-radius: 50px;
      font-size: 0.8rem;
      font-weight: 600;
      margin-bottom: 20px;
    }
    .hero h1 { color: var(--white); margin-bottom: 20px; }
    .hero p { color: rgba(255,255,255,0.8); font-size: 1.1rem; margin-bottom: 32px; line-height: 1.7; }
    .hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-image {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, rgba(196,30,58,0.2), rgba(27,58,92,0.3));
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .hero-image-placeholder {
      color: rgba(255,255,255,0.3);
      text-align: center;
    }
    .hero-image-placeholder i { font-size: 4rem; display: block; margin-bottom: 12px; }
    .hero-image-placeholder span { font-size: 0.85rem; }
    .hero-floating-stat {
      position: absolute;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(8px);
      border-radius: var(--radius-md);
      padding: 14px 20px;
      box-shadow: var(--shadow-lg);
    }
    .hero-floating-stat.stat-1 { bottom: -20px; left: -20px; }
    .hero-floating-stat.stat-2 { top: -20px; right: -20px; }
    .hero-floating-stat .stat-value { font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 1.3rem; color: var(--red); }
    .hero-floating-stat .stat-label { font-size: 0.75rem; color: var(--gray-500); }

    /* ===== MISSION ===== */
    .mission { background: var(--warm-gray); }
    .mission .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }
    .mission-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(196,30,58,0.08);
      color: var(--red);
      padding: 6px 16px;
      border-radius: 50px;
      font-size: 0.8rem;
      font-weight: 600;
      margin-bottom: 16px;
    }
    .mission h2 { margin-bottom: 16px; }
    .mission-statement {
      font-size: 1.15rem;
      font-weight: 600;
      color: var(--navy);
      line-height: 1.6;
      margin-bottom: 20px;
      padding-left: 20px;
      border-left: 4px solid var(--red);
    }
    .mission p { margin-bottom: 16px; line-height: 1.8; }
    .mission-image {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, rgba(27,58,92,0.1), rgba(196,30,58,0.08));
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .mission-image-placeholder {
      color: var(--gray-400);
      text-align: center;
    }
    .mission-image-placeholder i { font-size: 3.5rem; display: block; margin-bottom: 10px; }
    .mission-image-placeholder span { font-size: 0.85rem; }

    /* ===== IMPACT STATS ===== */
    .impact-stats {
      background: var(--navy);
      padding: 60px 0;
    }
    .impact-stats .section-label { color: rgba(255,255,255,0.6); }
    .impact-stats h2 { color: var(--white); text-align: center; margin-bottom: 48px; }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }
    .stat-card {
      text-align: center;
      padding: 32px 20px;
      border-radius: var(--radius-md);
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      transition: all var(--transition);
    }
    .stat-card:hover {
      background: rgba(255,255,255,0.1);
      transform: translateY(-2px);
    }
    .stat-icon {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: rgba(196,30,58,0.2);
      margin-bottom: 16px;
    }
    .stat-icon i { font-size: 1.4rem; color: var(--red-light); }
    .stat-number {
      font-family: 'Montserrat', sans-serif;
      font-size: clamp(1.8rem, 3vw, 2.5rem);
      font-weight: 800;
      color: var(--white);
      margin-bottom: 6px;
    }
    .stat-label { color: rgba(255,255,255,0.7); font-size: 0.9rem; }
    .stats-caption {
      text-align: center;
      color: rgba(255,255,255,0.5);
      font-size: 0.9rem;
      margin-top: 40px;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
      line-height: 1.6;
    }

    /* ===== PROGRAMS ===== */
    .programs { background: var(--white); }
    .programs-header { text-align: center; margin-bottom: 48px; }
    .programs-header h2 { margin-bottom: 12px; }
    .programs-header p { max-width: 560px; margin: 0 auto; }
    .accordion { max-width: 800px; margin: 0 auto; }
    .accordion-item {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      margin-bottom: 12px;
      overflow: hidden;
      transition: box-shadow var(--transition);
    }
    .accordion-item:hover { box-shadow: var(--shadow-sm); }
    .accordion-item.active { box-shadow: var(--shadow-md); border-color: var(--red); }
    .accordion-header {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 20px 24px;
      font-size: 1rem;
      font-weight: 600;
      color: var(--navy);
      text-align: left;
      transition: all var(--transition);
    }
    .accordion-header:hover { background: var(--gray-50); }
    .accordion-item.active .accordion-header { background: rgba(196,30,58,0.04); color: var(--red); }
    .accordion-icon-wrap {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      background: var(--gray-100);
      flex-shrink: 0;
      transition: all var(--transition);
    }
    .accordion-item.active .accordion-icon-wrap { background: rgba(196,30,58,0.1); }
    .accordion-icon-wrap i { font-size: 1.1rem; color: var(--navy); transition: color var(--transition); }
    .accordion-item.active .accordion-icon-wrap i { color: var(--red); }
    .accordion-chevron {
      margin-left: auto;
      font-size: 1.2rem;
      color: var(--gray-400);
      transition: transform 0.3s ease, color var(--transition);
    }
    .accordion-item.active .accordion-chevron { transform: rotate(180deg); color: var(--red); }
    .accordion-body {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.35s ease;
    }
    .accordion-body-inner {
      padding: 0 24px 24px 80px;
      color: var(--gray-600);
      line-height: 1.7;
    }
    .accordion-body-inner a {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      color: var(--red);
      font-weight: 600;
      font-size: 0.9rem;
      margin-top: 12px;
      transition: gap var(--transition);
    }
    .accordion-body-inner a:hover { gap: 8px; }

    /* ===== GET INVOLVED ===== */
    .get-involved { background: var(--warm-gray); }
    .get-involved-header { text-align: center; margin-bottom: 48px; }
    .get-involved-header h2 { margin-bottom: 12px; }
    .get-involved-header p { max-width: 560px; margin: 0 auto; }
    .involve-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
    .involve-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 40px 32px;
      text-align: center;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
      border: 1px solid var(--gray-100);
    }
    .involve-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
    .involve-icon {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 64px;
      height: 64px;
      border-radius: 50%;
      margin-bottom: 20px;
    }
    .involve-icon.red { background: rgba(196,30,58,0.1); }
    .involve-icon.red i { color: var(--red); font-size: 1.5rem; }
    .involve-icon.navy { background: rgba(27,58,92,0.1); }
    .involve-icon.navy i { color: var(--navy); font-size: 1.5rem; }
    .involve-icon.warm { background: rgba(234,88,12,0.1); }
    .involve-icon.warm i { color: #ea580c; font-size: 1.5rem; }
    .involve-card h3 { margin-bottom: 12px; }
    .involve-card p { font-size: 0.92rem; margin-bottom: 24px; line-height: 1.7; }

    /* ===== NEWS ===== */
    .news { background: var(--white); }
    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 40px;
    }
    .news-header h2 { margin-bottom: 4px; }
    .carousel-controls { display: flex; gap: 10px; }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      color: var(--gray-600);
      transition: all var(--transition);
    }
    .carousel-btn:hover { border-color: var(--red); color: var(--red); background: rgba(196,30,58,0.05); }
    .news-carousel { overflow: hidden; position: relative; }
    .news-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s ease;
    }
    .news-card {
      flex: 0 0 calc(33.333% - 16px);
      background: var(--white);
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      transition: all var(--transition);
    }
    .news-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
    .news-card-image {
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, rgba(27,58,92,0.08), rgba(196,30,58,0.06));
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-300);
      font-size: 2rem;
    }
    .news-card-body { padding: 24px; }
    .news-tag {
      display: inline-block;
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--red);
      margin-bottom: 10px;
    }
    .news-card h3 { font-size: 1.05rem; margin-bottom: 10px; color: var(--navy); }
    .news-card p { font-size: 0.88rem; line-height: 1.6; }

    /* ===== DONATE CTA ===== */
    .donate-cta {
      background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
      padding: 80px 0;
      position: relative;
      overflow: hidden;
    }
    .donate-cta::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -30%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);
    }
    .donate-cta .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
      position: relative;
      z-index: 2;
    }
    .donate-cta-content h2 { color: var(--white); margin-bottom: 16px; }
    .donate-cta-content p { color: rgba(255,255,255,0.85); font-size: 1.05rem; line-height: 1.7; margin-bottom: 16px; }
    .donate-cta-content .efficiency { color: rgba(255,255,255,0.6); font-size: 0.85rem; }
    .donate-cta-content .efficiency strong { color: var(--white); }
    .impact-table {
      background: rgba(255,255,255,0.1);
      backdrop-filter: blur(8px);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid rgba(255,255,255,0.15);
    }
    .impact-table h3 { color: var(--white); margin-bottom: 20px; font-size: 1.1rem; }
    .impact-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 14px 0;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .impact-row:last-child { border-bottom: none; }
    .impact-amount { color: var(--white); font-weight: 700; font-size: 1.1rem; font-family: 'Montserrat', sans-serif; }
