  <script>
    /* ===== HEADER SCROLL ===== */
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    /* ===== MOBILE MENU ===== */
    const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobileNav');
    const mobileOverlay = document.getElementById('mobileOverlay');

    function openMobileNav() {
      hamburger.classList.add('active');
      mobileNav.classList.add('open');
      mobileOverlay.style.display = 'block';
      requestAnimationFrame(() => mobileOverlay.classList.add('show'));
      document.body.style.overflow = 'hidden';
    }

    function closeMobileNav() {
      hamburger.classList.remove('active');
      mobileNav.classList.remove('open');
      mobileOverlay.classList.remove('show');
      setTimeout(() => { mobileOverlay.style.display = 'none'; }, 300);
      document.body.style.overflow = '';
    }

    hamburger.addEventListener('click', () => {
      mobileNav.classList.contains('open') ? closeMobileNav() : openMobileNav();
    });
    mobileOverlay.addEventListener('click', closeMobileNav);

    /* ===== DONATE MODAL ===== */
    const donateModal = document.getElementById('donateModal');

    function openDonateModal(e) {
      if (e) e.preventDefault();
      donateModal.style.display = 'flex';
      requestAnimationFrame(() => donateModal.classList.add('show'));
      document.body.style.overflow = 'hidden';
    }

    function closeDonateModal() {
      donateModal.classList.remove('show');
      setTimeout(() => { donateModal.style.display = 'none'; }, 300);
      document.body.style.overflow = '';
    }

    donateModal.addEventListener('click', (e) => {
      if (e.target === donateModal) closeDonateModal();
    });

    // Amount selection
    document.querySelectorAll('.amount-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
        btn.classList.add('selected');
        document.getElementById('customAmount').value = '';
      });
    });

    document.getElementById('customAmount').addEventListener('input', () => {
      document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
    });

    // Frequency toggle
    document.querySelectorAll('.frequency-option').forEach(opt => {
      opt.addEventListener('click', () => {
        document.querySelectorAll('.frequency-option').forEach(o => o.classList.remove('active'));
        opt.classList.add('active');
      });
    });

    function handleDonate() {
      const selected = document.querySelector('.amount-btn.selected');
      const custom = document.getElementById('customAmount').value;
      const freq = document.querySelector('.frequency-option.active').dataset.frequency;
      const amount = custom || (selected ? selected.dataset.amount : '0');
      alert(`Thank you for your ${freq === 'monthly' ? 'monthly' : 'one-time'} donation of $${amount}! In a real implementation, this would redirect to a secure payment processor.`);
    }

    /* ===== ANIMATED COUNTERS ===== */
    function animateCounters() {
      document.querySelectorAll('.stat-number').forEach(el => {
        const target = parseInt(el.dataset.target);
        const prefix = el.dataset.prefix || '';
        const suffix = el.dataset.suffix || '';
        const duration = 2000;
        const start = performance.now();

        function formatNumber(n) {
          if (n >= 1000000) return (n / 1000000).toFixed(0) + ' million';
          if (n >= 1000) return n.toLocaleString();
          return n.toString();
        }

        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.round(eased * target);
          el.textContent = prefix + formatNumber(current) + suffix;
          if (progress < 1) requestAnimationFrame(update);
        }

        requestAnimationFrame(update);
      });
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    statsObserver.observe(document.getElementById('impact'));

    /* ===== ACCORDION ===== */
    document.querySelectorAll('[data-accordion]').forEach(item => {
      const header = item.querySelector('.accordion-header');
      const body = item.querySelector('.accordion-body');

      header.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all
        document.querySelectorAll('[data-accordion]').forEach(other => {
          other.classList.remove('active');
          other.querySelector('.accordion-header').setAttribute('aria-expanded', 'false');
          other.querySelector('.accordion-body').style.maxHeight = '0';
        });

        // Toggle current
        if (!isActive) {
          item.classList.add('active');
          header.setAttribute('aria-expanded', 'true');
          body.style.maxHeight = body.scrollHeight + 'px';
        }
      });
    });

    /* ===== NEWS CAROUSEL ===== */
    const newsTrack = document.getElementById('newsTrack');
    const newsCards = newsTrack.querySelectorAll('.news-card');
    let newsIndex = 0;

    function getCardsPerView() {
      if (window.innerWidth <= 768) return 1;
      if (window.innerWidth <= 1024) return 2;
      return 3;
    }

    function updateCarousel() {
      const perView = getCardsPerView();
      const maxIndex = Math.max(0, newsCards.length - perView);
      newsIndex = Math.min(newsIndex, maxIndex);

      const card = newsCards[0];
      const gap = 24;
      const cardWidth = card.offsetWidth;
      const offset = newsIndex * (cardWidth + gap);
      newsTrack.style.transform = `translateX(-${offset}px)`;

      document.getElementById('newsPrev').style.opacity = newsIndex === 0 ? '0.4' : '1';
      document.getElementById('newsNext').style.opacity = newsIndex >= maxIndex ? '0.4' : '1';
    }

    document.getElementById('newsPrev').addEventListener('click', () => {
      if (newsIndex > 0) { newsIndex--; updateCarousel(); }
    });
    document.getElementById('newsNext').addEventListener('click', () => {
      const perView = getCardsPerView();
      const maxIndex = Math.max(0, newsCards.length - perView);
      if (newsIndex < maxIndex) { newsIndex++; updateCarousel(); }
    });

    window.addEventListener('resize', updateCarousel);
    updateCarousel();

    /* ===== SMOOTH SCROLL ===== */
    document.querySelectorAll('a[href^="#"]').forEach(link => {
      link.addEventListener('click', (e) => {
        const id = link.getAttribute('href');
        if (id === '#') return;
        e.preventDefault();
        const target = document.querySelector(id);
        if (target) {
          const headerH = document.querySelector('.header').offsetHeight;
          const y = target.getBoundingClientRect().top + window.scrollY - headerH;
          window.scrollTo({ top: y, behavior: 'smooth' });
        }
      });
    });

    /* ===== ESC KEY ===== */
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeDonateModal();
        closeMobileNav();
      }
    });
  </script>
